typeProperties.script:
section Section1;
shared Parquet1 = let AdfDoc = AzureStorage.BlobContents("https://sapowerquerytest.blob.core.windows.net/powequerytest/HandyCandy.parquet"), Parquet = Parquet.Document(AdfDoc) in Parquet;
shared UserQuery = let Source = #"Parquet1",
  #"Removed columns" = Table.RemoveColumns(Source, {"TransactionId", "StoreId"}),
  #"Inserted start of month" = Table.AddColumn(#"Removed columns", "Start of month", each Date.StartOfMonth([TransactionDate]), type nullable datetime),
  #"Added custom" = Table.AddColumn(#"Inserted start of month", "SalesMonth", each Date.AddDays([TransactionDate], 1 - Date.Day([TransactionDate]))),
  #"Removed columns 1" = Table.RemoveColumns(#"Added custom", {"TransactionDate"}),
  #"Grouped rows" = Table.Group(#"Removed columns 1", {"SalesMonth", "Product"}, {{"UnitsSold", each Table.RowCount(_), Int64.Type}, {"SalesValueUSD", each List.Sum([Price]), type nullable number}}),
  #"Added custom 1" = Table.AddColumn(#"Grouped rows", "Retailer", each "Handy Candy"),
  #"Changed column type" = Table.TransformColumnTypes(#"Added custom 1", {{"SalesMonth", type date}}) in #"Changed column type";
